"""Pure authenticated venue evidence, including captured historical Solana CPIs.

Captured rows come from the bounded four-read H4KUxs... window, saved 2026-10-04.
The compressed fixture contains public transaction evidence only; tests make no RPC calls.
"""
import base64
from copy import deepcopy
import importlib
import json
import zlib

import pytest

MINT = 'H4KUxsEgCp2yDpFvyDuGM5k6XevSKKrrKUxZ3Zr6nyJc'
PUMP_QUOTE = "pumpCmXqMfrsAkQ5r49WcJnRayYRqmXz6ae8H7H9Dfn"
WSOL = "So11111111111111111111111111111111111111112"
EXOTIC = "8ccrUHKj9LaucuPe3c8e3wY89QSNefqabqXCfyoojupx"
CAPTURED_UNIT = {'chain': 'solana', 'uid': '0bbbf8fd-dea4-5561-bd2e-54f98a573ff8', 'address': '6XpoayPqAE99XfCPARDig3CwU6Mg7pMdrTCCbqVidZMV', 'mint': 'H4KUxsEgCp2yDpFvyDuGM5k6XevSKKrrKUxZ3Zr6nyJc', 'signature': '5YcHnQvszDHsrNgHMNixkyadyBwk8c5wVhmbwbymj4i7t9ZRSdgfBH6tGwaQGvcF3P9eUYkMd5bN4PgBT5QKXMzV', 't0': 1790699261}
_CAPTURED = {'source': '', 'pump_sell': '', 'pump_dlmm': '', 'pump_damm': '', 'unused_router': ''}


def captured_tx(name):
    return json.loads(zlib.decompress(base64.b64decode(_CAPTURED[name])))


@pytest.fixture
def venues():
    return importlib.import_module("sniper.services.wallet_universe_sol_venues")


def test_real_pump_sell_uses_quote_vault_debit_in_actual_pump_units(venues):
    tx = captured_tx("pump_sell")
    result = venues.decode_transaction(tx, MINT)
    assert result["status"] == "trade" and len(result["swaps"]) == 1
    swap = result["swaps"][0]
    assert swap["protocol"] == "pumpswap"
    assert swap["quote"] == dict(asset=PUMP_QUOTE, symbol=None, decimals=6, amount="-318104016")
    assert swap["mint_delta_atomic"] == "3534673024"
    # Signer's quote receipt is 314757230; it must never substitute for the venue debit.
    assert swap["quote"]["amount"] != "-314757230"


def test_real_arbitrage_decodes_both_target_pool_legs_without_mixing_quotes(venues):
    result = venues.decode_transaction(captured_tx("pump_dlmm"), MINT)
    assert result["status"] == "trade" and len(result["swaps"]) == 2
    q = {swap["quote"]["asset"]:swap["quote"] for swap in result["swaps"]}
    assert q[WSOL]["amount"] == "455439204" and q[WSOL]["decimals"] == 9
    assert q[PUMP_QUOTE]["amount"] == "-9515368347" and q[PUMP_QUOTE]["decimals"] == 6


def test_real_pump_buy_and_damm_sell_preserve_their_two_exotic_quote_mints(venues):
    result = venues.decode_transaction(captured_tx("pump_damm"), MINT)
    assert result["status"] == "trade" and len(result["swaps"]) == 2
    q = {swap["quote"]["asset"]:swap["quote"] for swap in result["swaps"]}
    assert q[PUMP_QUOTE]["amount"] == "22825381"
    assert q[EXOTIC]["amount"] == "-33483562634" and q[EXOTIC]["decimals"] == 6


def test_real_unused_router_target_accounts_are_not_swaps(venues):
    result = venues.decode_transaction(captured_tx("unused_router"), MINT)
    assert result["status"] == "nontrade" and result["swaps"] == []


@pytest.mark.parametrize("mutation", ["failed", "missing_inner", "missing_stack", "missing_runtime",
    "wrong_vault", "wrong_decimals", "missing_balance", "duplicate_event", "event_actor",
    "unknown_program", "unsupported_discriminator", "truncated_logs", "unmatched_target_transfer"])
def test_captured_negative_evidence_never_becomes_usable_flow(venues, mutation):
    tx = captured_tx("pump_sell")
    keys = tx["transaction"]["message"]["accountKeys"]
    keys += tx["meta"]["loadedAddresses"]["writable"] + tx["meta"]["loadedAddresses"]["readonly"]
    tx["meta"]["loadedAddresses"] = dict(writable=[],readonly=[])
    pump = next(ix for group in tx["meta"]["innerInstructions"] for ix in group["instructions"]
        if keys[ix["programIdIndex"]] == venues.PUMP and len(ix["accounts"]) >= 21)
    if mutation == "failed": tx["meta"]["err"] = {"InstructionError":[0,"Custom"]}
    if mutation == "missing_inner": tx["meta"].pop("innerInstructions")
    if mutation == "missing_stack": pump.pop("stackHeight")
    if mutation == "missing_runtime": tx["meta"]["logMessages"] = []
    if mutation == "wrong_vault": pump["accounts"][8] = pump["accounts"][6]
    if mutation == "wrong_decimals":
        quote = next(b for b in tx["meta"]["postTokenBalances"] if b["mint"] == PUMP_QUOTE)
        quote["uiTokenAmount"]["decimals"] += 1
    if mutation == "missing_balance": tx["meta"]["preTokenBalances"] = []
    if mutation in ("duplicate_event", "event_actor"):
        line_index = next(i for i,line in enumerate(tx["meta"]["logMessages"])
            if line.startswith("Program data: "))
        if mutation == "duplicate_event": tx["meta"]["logMessages"].insert(line_index,tx["meta"]["logMessages"][line_index])
        else:
            raw = bytearray(base64.b64decode(tx["meta"]["logMessages"][line_index][14:]));raw[152] ^= 1
            tx["meta"]["logMessages"][line_index] = "Program data: " + base64.b64encode(raw).decode()
    if mutation == "unknown_program":
        original=venues.PUMP; replacement="11111111111111111111111111111111"
        keys[keys.index(original)] = replacement
        tx["meta"]["logMessages"] = [s.replace(original,replacement) for s in tx["meta"]["logMessages"]]
    if mutation == "unsupported_discriminator": pump["data"] = "111111111111111111111111"
    if mutation == "truncated_logs": tx["meta"]["logMessages"].append("Log truncated incorrectly")
    if mutation == "unmatched_target_transfer":
        # Move an actual target transfer outside the authenticated swap CPI by changing its depth.
        target = next(ix for group in tx["meta"]["innerInstructions"] for ix in group["instructions"]
            if keys[ix["programIdIndex"]] in venues.TOKEN_PROGRAMS and pump["accounts"][3] in ix["accounts"])
        target["stackHeight"] = pump["stackHeight"]
    with pytest.raises(venues.SolVenueDecodeError):venues.decode_transaction(tx,MINT)


def test_real_captured_window_subset_collects_only_authenticated_venue_flow():
    from sniper.services import wallet_universe_flow as flow
    unit = {**CAPTURED_UNIT,"probe_age":False}
    rows = [captured_tx(name) for name in ("source","pump_dlmm","pump_sell","pump_damm")]
    result = flow.collect_solana(unit,lambda *_:dict(data=rows,paginationToken=None))
    assert result["status"] == "complete" and result["after_complete"] is True
    assert result["method"] == "wallet-universe-flow-v7"
    assert result["flow_basis"] == "signed_pool_vault_quote_v1"
    q = {q["asset"]:q for q in result["quotes"]}
    assert q[PUMP_QUOTE]["net_after_atomic"] == str(-9515368347-318104016+22825381)
    assert q[EXOTIC]["net_after_atomic"] == "-33483562634"
    assert q[WSOL]["net_after_atomic"] == "455439204"


def synthetic_swap(**kwargs):
    import runpy
    return runpy.run_path("tests/test_wallet_universe_flow.py")["sol_tx"]("roundtrip", 1001, 1, **kwargs)


def test_two_executed_same_pool_swaps_are_retained_even_with_zero_wallet_delta(venues):
    tx = synthetic_swap(paid=100, bought=10)
    sell = synthetic_swap(paid=-100, bought=-10)
    tx["transaction"]["message"]["instructions"].extend(sell["transaction"]["message"]["instructions"])
    group = sell["meta"]["innerInstructions"][0]
    group["index"] = 1
    tx["meta"]["innerInstructions"].append(group)
    tx["meta"]["logMessages"].extend(sell["meta"]["logMessages"])
    tx["meta"]["postTokenBalances"] = deepcopy(tx["meta"]["preTokenBalances"])
    mint = tx["meta"]["preTokenBalances"][0]["mint"]
    result = venues.decode_transaction(tx, mint)
    assert result["status"] == "trade" and len(result["swaps"]) == 2
    assert [s["quote"]["amount"] for s in result["swaps"]] == ["100", "-100"]
    assert all(s["actor_verified"] for s in result["swaps"])


def test_authenticated_lp_deposit_is_a_nontrade(venues):
    import base58
    import hashlib
    tx = synthetic_swap(paid=100, bought=-10)
    root = tx["transaction"]["message"]["instructions"][0]
    root["data"] = base58.b58encode(hashlib.sha256(b"global:deposit").digest()[:8] + bytes(24)).decode()
    tx["meta"]["innerInstructions"][0]["instructions"].pop()
    token = next(iter(venues.TOKEN_PROGRAMS - {"TokenzQdBNbLqP5VEhdkAS6EPFLC1PHnBqCXEpPxuEb"}))
    tx["meta"]["logMessages"] = ["Program " + venues.PUMP + " invoke [1]",
        "Program log: Instruction: Deposit", "Program " + token + " invoke [2]",
        "Program " + token + " success", "Program " + token + " invoke [2]",
        "Program " + token + " success", "Program " + venues.PUMP + " success"]
    mint = tx["meta"]["preTokenBalances"][0]["mint"]
    result = venues.decode_transaction(tx, mint)
    assert result["status"] == "nontrade" and result["swaps"] == []


def test_v6_resume_binding_rejects_prechange_cash_basis():
    from sniper.services import wallet_universe_flow as flow
    rows = [captured_tx("source")]
    unit = {**CAPTURED_UNIT, "probe_age":False}
    result = flow.collect_solana(unit, lambda *_:dict(data=rows,paginationToken=None))
    state = deepcopy(result["state"])
    state["binding"]["flow_basis"] = "signer_cash"
    with pytest.raises(ValueError, match="state_identity_mismatch"):
        flow.collect_solana(unit, lambda *_:pytest.fail("must not read"), state=state)


def test_real_dbc_hook_binds_vault_units_without_assigning_pda_actor(venues):
    result=venues.decode_transaction(captured_tx("dbc_hook"),DBC_UNIT["mint"])
    assert result["status"]=="trade" and len(result["swaps"])==1
    swap=result["swaps"][0]
    assert swap["protocol"]=="meteora_dbc" and swap["actor_verified"] is False
    assert swap["actor"]=="ARu4n5mFdZogZAravu7CcizaojWnS6oqka37gdLT5SZn"
    assert swap["mint_delta_atomic"]=="-2070326650280"
    assert swap["quote"]==dict(asset=WSOL,symbol="SOL",decimals=9,amount="21202296232")
    # The curve receives 20,990,273,269; actual vault cash includes trading/protocol fees.
    assert swap["quote"]["amount"]!="20990273269"
    proof=swap["economic_source_proof"]
    assert proof["signer"]==DBC_UNIT["address"] and proof["actor_verified"] is False
    assert proof["payment"]==dict(asset="EPjFWdd5AufqSSqeM2qN1xzybapC8G4wEGGkZwyTDt1v",decimals=6,amount="2500000000")
    assert proof["received_atomic"]=="2070326650280" and len(proof["conversions"])==2


@pytest.mark.parametrize("mutation",["authority","pool","config","vault","payer","token_program",
    "event_authority","event_pool","event_config","event_amount","event_direction","duplicate_event",
    "missing_event","hook_extension","vault_balance","decimals"])
def test_dbc_wrong_venue_event_or_vault_evidence_is_censored(venues,mutation):
    import base58
    tx=captured_tx("dbc_hook")
    keys=tx["transaction"]["message"]["accountKeys"]
    keys+=tx["meta"]["loadedAddresses"]["writable"]+tx["meta"]["loadedAddresses"]["readonly"]
    tx["meta"]["loadedAddresses"]=dict(writable=[],readonly=[])
    group=next(g for g in tx["meta"]["innerInstructions"] if any(keys[c["programIdIndex"]].startswith("dbc") and len(c["accounts"])>=15 for c in g["instructions"]))
    swap=next(c for c in group["instructions"] if keys[c["programIdIndex"]].startswith("dbc") and len(c["accounts"])>=15)
    event=next(c for c in group["instructions"] if keys[c["programIdIndex"]].startswith("dbc") and len(c["accounts"])==1)
    if mutation in ("authority","pool","config","vault","payer","token_program","event_authority"):
        position={"authority":0,"pool":2,"config":1,"vault":5,"payer":9,"token_program":10,"event_authority":13}[mutation]
        swap["accounts"][position]=0
    if mutation in ("event_pool","event_config","event_amount","event_direction"):
        raw=bytearray(base58.b58decode(event["data"]))
        raw[{"event_pool":16,"event_config":48,"event_amount":99,"event_direction":80}[mutation]]^=1
        event["data"]=base58.b58encode(raw).decode()
    if mutation=="duplicate_event":
        c=deepcopy(event);group["instructions"].insert(group["instructions"].index(event),c)
    if mutation=="missing_event": group["instructions"].remove(event)
    if mutation=="hook_extension":
        transfer=next(c for c in group["instructions"] if c["accounts"][:3]==[swap["accounts"][5],swap["accounts"][7],swap["accounts"][4]])
        raw=bytearray(base58.b58decode(transfer["data"]));raw[0]=26
        transfer["data"]=base58.b58encode(raw).decode()
    if mutation=="vault_balance":
        next(b for b in tx["meta"]["postTokenBalances"] if b["accountIndex"]==swap["accounts"][6])["uiTokenAmount"]["amount"]="1"
    if mutation=="decimals":
        next(b for b in tx["meta"]["postTokenBalances"] if b["accountIndex"]==swap["accounts"][5])["uiTokenAmount"]["decimals"]=9
    with pytest.raises(venues.SolVenueDecodeError):venues.decode_transaction(tx,DBC_UNIT["mint"])


