# Public DBC transfer-hook transaction, captured 2026-10-04; no credentials.
_CAPTURED["dbc_hook"] = ''
DBC_UNIT = {'chain': 'solana', 'address': 'V8c7i9prMkHT7fdMScUdZcZUjPmVJKFpTiVbzbaE2Bt', 'mint': 'DioisRY2M15WKza2te7pCvEAe7B1EVp4N1ZrM6tn52Sp', 'signature': '5hK5ysdSasGK7GQVrg1J2qXn1mDgtkSVirqtp4sznKHkhaceyHcGHyMiskmFngtKU9tHjx3E8w2gvSPtfz9DqfPt', 't0': 1790974519, 'source_slot': 452723780, 'uid': 'captured-dbc', 'probe_age': False}


def dbc_parts(tx):
    """Resolve public compiled indexes without inventing a runtime parser."""
    from sniper.services import wallet_universe_sol_venues as venues
    keys=tx["transaction"]["message"]["accountKeys"]
    keys+=tx["meta"]["loadedAddresses"]["writable"]+tx["meta"]["loadedAddresses"]["readonly"]
    tx["meta"]["loadedAddresses"]=dict(writable=[],readonly=[])
    group=next(g for g in tx["meta"]["innerInstructions"] if any(keys[c["programIdIndex"]]==venues.DBC and len(c["accounts"])>=15 for c in g["instructions"]))
    swap=next(c for c in group["instructions"] if keys[c["programIdIndex"]]==venues.DBC and len(c["accounts"])>=15)
    event=next(c for c in group["instructions"] if keys[c["programIdIndex"]]==venues.DBC and len(c["accounts"])==1)
    return keys,group,swap,event


def dbc_followup(buyer=None):
    import base58
    tx=captured_tx("dbc_hook")
    keys,_,_,event=dbc_parts(tx)
    tx["blockTime"]+=1;tx["slot"]+=1
    tx["transaction"]["signatures"]=["public-follow-up", "public-secondary-signature"]
    raw=bytearray(base58.b58decode(event["data"]));raw[187:195]=(tx["blockTime"]).to_bytes(8,"little")
    event["data"]=base58.b58encode(raw).decode()
    if buyer:
        keys[keys.index(DBC_UNIT["address"])]=buyer
        for side in ("preTokenBalances","postTokenBalances"):
            for s in tx["meta"][side]:
                if s["owner"]==DBC_UNIT["address"]:s["owner"]=buyer
        for group in tx["meta"]["innerInstructions"]:
            for c in group["instructions"]:
                raw=base58.b58decode(c["data"])
                if raw[:1]==b"\x12" and len(raw)==33 and base58.b58encode(raw[1:]).decode()==DBC_UNIT["address"]:
                    c["data"]=base58.b58encode(b"\x12"+base58.b58decode(buyer)).decode()
    return tx


def test_routed_followup_source_buyer_is_excluded_without_verifying_protocol_pda():
    from sniper.services import wallet_universe_flow as flow
    result=flow.collect_solana(DBC_UNIT,lambda *_:dict(data=[captured_tx("dbc_hook"),dbc_followup()],paginationToken=None))
    assert result["status"]=="complete" and result["quotes"]==[]


def test_routed_followup_alias_exclusion_requires_actual_signer_payment_proof():
    from sniper.services import wallet_universe_flow as flow
    import base58,hashlib
    alias=base58.b58encode(hashlib.sha256(b"public route alias").digest()).decode()
    post=dbc_followup(alias)
    kept=flow.collect_solana(DBC_UNIT,lambda *_:dict(data=[captured_tx("dbc_hook"),post],paginationToken=None))
    assert kept["status"]=="complete" and kept["quotes"][0]["net_after_atomic"]=="21202296232"
    excluded=flow.collect_solana(DBC_UNIT,lambda *_:dict(data=[captured_tx("dbc_hook"),post],paginationToken=None),excluded_addresses=[alias])
    assert excluded["status"]=="complete" and excluded["quotes"]==[]


def dbc_runtime_logs(tx, keys):
    """Synthetic mutations retain a complete successful CPI envelope."""
    groups={g["index"]:g["instructions"] for g in tx["meta"]["innerInstructions"]}
    logs=[]
    for i,root in enumerate(tx["transaction"]["message"]["instructions"]):
        stack=[]
        for c in [root]+groups.get(i,[]):
            height=c.get("stackHeight",1)
            while len(stack)>=height:logs.append("Program "+stack.pop()+" success")
            program=keys[c["programIdIndex"]]
            logs.append(f"Program {program} invoke [{height}]")
            stack.append(program)
        while stack:logs.append("Program "+stack.pop()+" success")
    tx["meta"]["logMessages"]=logs


def dbc_unproved_route(mutation):
    import base58
    tx=captured_tx("dbc_hook")
    keys,group,swap,event=dbc_parts(tx)
    funding=group["instructions"][0] # Exact source-signer USDC transfer.
    payment_escrow=funding["accounts"][2]
    if mutation=="debit_authority":funding["accounts"][3]=0
    if mutation=="debit_source_owner":
        for side in ("preTokenBalances","postTokenBalances"):
            next(s for s in tx["meta"][side] if s["accountIndex"]==funding["accounts"][0])["owner"]=keys[0]
    if mutation=="recipient_gift":
        next(s for s in tx["meta"]["postTokenBalances"] if s["accountIndex"]==swap["accounts"][4])["owner"]=keys[0]
    if mutation in ("payment_inventory_depleted","quote_inventory_depleted"):
        account=payment_escrow if mutation=="payment_inventory_depleted" else swap["accounts"][3]
        balance=next(s for s in tx["meta"]["postTokenBalances"] if s["accountIndex"]==account)["uiTokenAmount"]
        balance["amount"]=str(int(balance["amount"])-100)
        if mutation=="quote_inventory_depleted":tx["meta"]["postBalances"][account]-=100
    if mutation=="unrelated_debit_plus_gift":
        # USDC payment remains inside conversion CPI; its quote credit is now
        # a separate outer-router transfer and cannot prove a paid conversion.
        quote=next(c for c in group["instructions"] if c["accounts"][:3]==[keys.index("5pVN5XZB8cYBjNLFrsBCPWkCQBan5K5Mq2dWGzwPgGJV"),swap["accounts"][8],swap["accounts"][3]])
        quote["stackHeight"]=2
        dbc_runtime_logs(tx,keys)
    if mutation=="unproved_new_output":
        initializer=next(c for g in tx["meta"]["innerInstructions"] for c in g["instructions"]
                         if base58.b58decode(c["data"])[:1]==b"\x12" and c["accounts"][0]==swap["accounts"][4])
        initializer["data"]=base58.b58encode(b"\x12"+base58.b58decode(keys[0])).decode()
    if mutation=="foreign_funding_closed_inventory":
        # The escrow still closes, but 100 atomic USDC now comes from a real
        # counterparty vault rather than the tracked signer.
        raw=bytearray(base58.b58decode(funding["data"]));raw[1:9]=(2500000000-100).to_bytes(8,"little")
        funding["data"]=base58.b58encode(raw).decode()
        source=next(s for s in tx["meta"]["postTokenBalances"] if s["accountIndex"]==funding["accounts"][0])["uiTokenAmount"]
        source["amount"]=str(int(source["amount"])+100)
        vault=keys.index("9t4P5wMwfFkyn92Z7hf463qYKEZf8ERVZsGBEPNp8uJx")
        foreign=deepcopy(funding);foreign["accounts"]=[vault,funding["accounts"][1],payment_escrow,
            keys.index("8ekCy2jHHUbW2yeNGFWYJT9Hm9FW7SvZcZK66dSZCDiF")]
        foreign["stackHeight"]=3
        foreign["data"]=base58.b58encode(b"\x0c"+(100).to_bytes(8,"little")+b"\x06").decode()
        group["instructions"].insert(5,foreign)
        balance=next(s for s in tx["meta"]["postTokenBalances"] if s["accountIndex"]==vault)["uiTokenAmount"]
        balance["amount"]=str(int(balance["amount"])-100)
        dbc_runtime_logs(tx,keys)
    return tx


@pytest.mark.parametrize("mutation",["debit_authority","debit_source_owner","recipient_gift",
    "payment_inventory_depleted","quote_inventory_depleted","unrelated_debit_plus_gift",
    "unproved_new_output","foreign_funding_closed_inventory"])
def test_dbc_valid_venue_with_unproved_payment_never_binds_tracked_source(venues,mutation):
    from sniper.services import wallet_universe_flow as flow
    tx=dbc_unproved_route(mutation)
    swap=venues.decode_transaction(tx,DBC_UNIT["mint"])["swaps"][0]
    assert swap["quote"]["amount"]=="21202296232" and swap["actor_verified"] is False
    assert "economic_source_proof" not in swap and swap["economic_source_gap"].startswith("routed_payment_")
    result=flow.collect_solana(DBC_UNIT,lambda *_:dict(data=[tx],paginationToken=None))
    assert result["status"]=="censored" and result["source_found"] is False
    assert result["quotes"]==[] and result["source_proof"] is None


def test_unproved_routed_post_buyer_stays_unattributed_and_is_not_excluded(venues):
    from sniper.services import wallet_universe_flow as flow
    tx=dbc_unproved_route("debit_authority")
    keys,_,_,event=dbc_parts(tx)
    import base58
    tx["blockTime"]+=1;tx["slot"]+=1;tx["transaction"]["signatures"]=["unproved-post"]
    raw=bytearray(base58.b58decode(event["data"]));raw[187:195]=tx["blockTime"].to_bytes(8,"little")
    event["data"]=base58.b58encode(raw).decode()
    result=flow.collect_solana(DBC_UNIT,lambda *_:dict(data=[captured_tx("dbc_hook"),tx],paginationToken=None))
    assert result["status"]=="complete" and result["quotes"][0]["net_after_atomic"]=="21202296232"
    record=result["state"]["records"][0]
    assert record["actor_verified"] is False and record["payment_signer"] is None
    assert "unproved routed payers remain unattributed" in result["owner_exclusion_detail"]


def test_resume_rejects_old_partial_or_complete_state_before_any_read():
    from sniper.services import wallet_universe_flow as flow
    result=flow.collect_solana(DBC_UNIT,lambda *_:dict(data=[captured_tx("dbc_hook")],paginationToken=None))
    for version in ("wallet-universe-flow-v5", "wallet-universe-flow-v6"):
        for complete in (False,True):
            old=deepcopy(result["state"]);old["version"]=version;old["complete"]=complete
            with pytest.raises(ValueError,match="state_identity_mismatch"):
                flow.collect_solana(DBC_UNIT,lambda *_:pytest.fail("old state must not read"),state=old)


def dbc_output_fee_tx(direction=1,mode=0):
    """Synthetic official fee/mode vectors around the real authenticated CPI.

    Captured transaction stays separately immutable. These vectors exercise
    legal OutputToken fees; the authenticated vault cash never includes a
    second subtraction of the event's retained trading/protocol fee.
    """
    import base58,struct
    tx=captured_tx("dbc_hook")
    keys,group,swap,event=dbc_parts(tx)
    event_raw=bytearray(base58.b58decode(event["data"]))
    instruction_raw=bytearray(base58.b58decode(swap["data"]))
    if direction==0:
        # Isolate one successful DBC sell CPI, with the hook on base input.
        base_in=2070326650280;quote_out=21202296232
        swap["accounts"][3],swap["accounts"][4]=swap["accounts"][4],swap["accounts"][3]
        swap["accounts"][9]=keys.index(DBC_UNIT["address"])
        input_cpi=group["instructions"][11] # Original DBC quote transfer.
        base_cpi=group["instructions"][12]
        hook_cpi=group["instructions"][13]
        input_cpi["accounts"]=[swap["accounts"][6],swap["accounts"][8],swap["accounts"][4],swap["accounts"][0]]
        base_cpi["accounts"][:4]=[swap["accounts"][3],swap["accounts"][7],swap["accounts"][5],swap["accounts"][9]]
        hook_cpi["accounts"][:4]=base_cpi["accounts"][:4]
        event_raw[80]=0
        event_raw[99:107]=base_in.to_bytes(8,"little")
        event_raw[107:115]=base_in.to_bytes(8,"little")
        event_raw[123:131]=quote_out.to_bytes(8,"little")
        old=[input_cpi,base_cpi,hook_cpi,event]
        swap.pop("stackHeight",None)
        for c in old:c["stackHeight"]-=1
        tx["transaction"]["message"]["instructions"]=[swap]
        tx["meta"]["innerInstructions"]=[dict(index=0,instructions=old)]
        for field in ("preTokenBalances","postTokenBalances"):
            if field=="preTokenBalances":
                receiver=deepcopy(next(s for s in tx["meta"]["postTokenBalances"] if s["accountIndex"]==swap["accounts"][3]))
                tx["meta"][field].append(receiver)
            for s in tx["meta"][field]:
                if s["accountIndex"]==swap["accounts"][3]:s["uiTokenAmount"]["amount"]=str(base_in if field=="preTokenBalances" else 0)
        for vault,delta in ((swap["accounts"][5],base_in),(swap["accounts"][6],-quote_out)):
            pre=next(s for s in tx["meta"]["preTokenBalances"] if s["accountIndex"]==vault)
            post=next(s for s in tx["meta"]["postTokenBalances"] if s["accountIndex"]==vault)
            post["uiTokenAmount"]["amount"]=str(int(pre["uiTokenAmount"]["amount"])+delta)
            if vault==swap["accounts"][6]:tx["meta"]["postBalances"][vault]=tx["meta"]["preBalances"][vault]+delta
        dbc_runtime_logs(tx,keys)
    included,_,_,output=struct.unpack_from("<4Q",event_raw,99)
    event_raw[107:115]=included.to_bytes(8,"little") # Excluded equals included on output fee.
    left=100 if mode==1 else 0
    event_raw[115:123]=left.to_bytes(8,"little")
    params=struct.pack("<QQB",output if mode==2 else included+left,included if mode==2 else 1,mode)
    instruction_raw[8:25]=params
    event_raw[82:99]=params
    swap["data"]=base58.b58encode(instruction_raw).decode()
    event["data"]=base58.b58encode(event_raw).decode()
    return tx


@pytest.mark.parametrize("direction",[0,1])
@pytest.mark.parametrize("mode",[0,1,2])
def test_dbc_output_fee_modes_measure_only_actual_signed_vault_cash(venues,direction,mode):
    result=venues.decode_transaction(dbc_output_fee_tx(direction,mode),DBC_UNIT["mint"])
    swap=result["swaps"][0]
    assert swap["quote"]["asset"]==WSOL and swap["quote"]["decimals"]==9
    assert swap["quote"]["amount"]==("-21202296232" if direction==0 else "21202296232")
    assert swap["mint_delta_atomic"]==("2070326650280" if direction==0 else "-2070326650280")


