@pytest.mark.parametrize("mutation",["included","excluded","input_fee_on_sell","gross_output_overflow",
    "instruction_amount","event_direction","transfer_amount","vault_balance","truncated_logs"])
def test_real_dbc_output_fee_still_censors_incoherent_evidence(venues,mutation):
    import base58
    tx=captured_dbc_output_fee()
    keys,group,swap,event=dbc_parts(tx)
    raw=bytearray(base58.b58decode(event["data"]))
    if mutation in ("included","excluded"):
        offset=99 if mutation=="included" else 107
        raw[offset:offset+8]=(int.from_bytes(raw[offset:offset+8],"little")+1).to_bytes(8,"little")
    if mutation=="input_fee_on_sell":
        included=int.from_bytes(raw[99:107],"little")
        fees=int.from_bytes(raw[147:155],"little")+int.from_bytes(raw[155:163],"little")
        raw[107:115]=(included-fees).to_bytes(8,"little")
    if mutation=="gross_output_overflow":raw[147:155]=((1<<64)-1).to_bytes(8,"little")
    if mutation=="event_direction":raw[80]=1
    event["data"]=base58.b58encode(raw).decode()
    if mutation=="instruction_amount":
        arg=bytearray(base58.b58decode(swap["data"]));arg[8]^=1;swap["data"]=base58.b58encode(arg).decode()
    if mutation=="transfer_amount":
        transfer=next(c for c in group["instructions"] if c["accounts"][:3]==[swap["accounts"][6],swap["accounts"][8],swap["accounts"][4]])
        amount=bytearray(base58.b58decode(transfer["data"]));amount[1]^=1;transfer["data"]=base58.b58encode(amount).decode()
    if mutation=="vault_balance":
        amount=next(s for s in tx["meta"]["postTokenBalances"] if s["accountIndex"]==swap["accounts"][6])["uiTokenAmount"]
        amount["amount"]=str(int(amount["amount"])+1)
    if mutation=="truncated_logs":tx["meta"]["logMessages"].append("Log truncated incorrectly")
    with pytest.raises(venues.SolVenueDecodeError):venues.decode_transaction(tx,DBC_UNIT["mint"])


