def test_real_truncated_marker_tail_is_not_a_continuous_runtime_suffix(venues):
    tx=captured_truncated_traces()[1]
    assert tx["meta"]["logMessages"][-1]=="Program log: Instruction: CloseAccount"
    # The runtime's remaining byte room permits short later logs. Never attach
    # those messages to an invented continuous stack after the marker.
    tx["meta"]["logMessages"]+=["Program log: Instruction: CloseAccount"]
    result=venues.decode_transaction(tx,MINT)
    assert result["status"]=="trade" and result["evidence_provenance"]=="compiled_instruction_trace_v1"


