def test_runtime_failure_after_truncation_marker_independently_censors(venues,program):
    tx=captured_truncated_traces()[0]
    tx["meta"]["logMessages"].append(f"Program {program} failed: custom program error: 0x1")
    # Tail messages cannot supply a continuous stack, but this failure line is
    # independent negative evidence. Successful top-level metadata cannot waive it.
    with pytest.raises(venues.SolVenueDecodeError,match="observed_runtime_cpi_failure"):
        venues.decode_transaction(tx,MINT)


