@pytest.mark.parametrize("mutation",["missing_inner","missing_height","string_height","wrong_height",
    "wrong_group_parent","duplicate_group","missing_data","bad_data","out_of_range_key",
    "contradictory_prefix","prefix_failed_cpi","malformed_marker","missing_marker","duplicate_marker",
    "event_authority","event_parent","event_identity","missing_event","duplicate_event",
    "vault_balance","unknown_venue","failed_meta","missing_loaded"])
def test_truncated_trace_recovery_never_waives_bad_evidence(venues,mutation):
    import base58
    tx=captured_truncated_traces()[0]
    keys,_,_=venues._keys_and_states(tx)
    nodes=venues._calls(tx,keys)
    groups={g["index"]:g["instructions"] for g in tx["meta"]["innerInstructions"]}
    flat=[c for i,root in enumerate(tx["transaction"]["message"]["instructions"]) for c in [root]+groups.get(i,[])]
    node=next(n for n in nodes if n.program==venues.PUMP and n.raw()[:8] in venues._SWAPS[venues.PUMP] and n.accounts[3]==MINT)
    event_node=next(n for n in node.children if n.program==venues.PUMP and n.raw()[:8]==venues.EVENT_IX)
    swap,event=flat[node.ordinal],flat[event_node.ordinal]
    group=next(g for g in tx["meta"]["innerInstructions"] if event in g["instructions"])
    # Flattening preserves the actual recorded indexes, not account ownership.
    tx["transaction"]["message"]["accountKeys"]=keys
    tx["meta"]["loadedAddresses"]=dict(writable=[],readonly=[])
    if mutation=="missing_inner":tx["meta"].pop("innerInstructions")
    if mutation=="missing_height":event.pop("stackHeight")
    if mutation=="string_height":event["stackHeight"]=str(event["stackHeight"])
    if mutation=="wrong_height":event["stackHeight"]+=2
    if mutation=="wrong_group_parent":group["index"]=len(tx["transaction"]["message"]["instructions"])
    if mutation=="duplicate_group":tx["meta"]["innerInstructions"].append(deepcopy(group))
    if mutation=="missing_data":flat[-1].pop("data")
    if mutation=="bad_data":flat[-1]["data"]="0Ol"
    if mutation=="out_of_range_key":event["accounts"][0]=len(keys)
    if mutation=="contradictory_prefix":tx["meta"]["logMessages"][0]="Program incorrect-prefix invoke [1]"
    if mutation=="prefix_failed_cpi":
        logs=tx["meta"]["logMessages"];i=next(i for i,x in enumerate(logs) if x.endswith(" success"))
        logs[i]=logs[i].removesuffix(" success")+" failed: custom program error: 0x1"
    if mutation=="malformed_marker":
        logs=tx["meta"]["logMessages"];logs[logs.index("Log truncated")]="Log truncated incorrectly"
    if mutation=="missing_marker":tx["meta"]["logMessages"].remove("Log truncated")
    if mutation=="duplicate_marker":tx["meta"]["logMessages"].append("Log truncated")
    if mutation=="event_authority":swap["accounts"][15]=0;event["accounts"][0]=0
    if mutation=="event_parent":event["stackHeight"]=swap["stackHeight"]
    if mutation=="event_identity":
        raw=bytearray(base58.b58decode(event["data"]));raw[160]^=1
        event["data"]=base58.b58encode(raw).decode()
    if mutation=="missing_event":group["instructions"].remove(event)
    if mutation=="duplicate_event":group["instructions"].insert(group["instructions"].index(event),deepcopy(event))
    if mutation=="vault_balance":
        amount=next(s for s in tx["meta"]["postTokenBalances"] if s["accountIndex"]==swap["accounts"][7])["uiTokenAmount"]
        amount["amount"]=str(int(amount["amount"])+1)
    if mutation=="unknown_venue":
        replacement="unknown-target-venue"
        keys[keys.index(venues.PUMP)]=replacement
        tx["meta"]["logMessages"]=[s.replace(venues.PUMP,replacement) for s in tx["meta"]["logMessages"]]
    if mutation=="failed_meta":tx["meta"]["err"]={"InstructionError":[0,"InvalidInstructionData"]}
    if mutation=="missing_loaded":tx["meta"].pop("loadedAddresses")
    with pytest.raises(venues.SolVenueDecodeError):venues.decode_transaction(tx,MINT)


